,p_protection_level=>'C'
,p_page_component_map=>'13'
,p_created_on=>wwv_flow_imp.dz('20260804085231Z')
,p_last_updated_on=>wwv_flow_imp.dz('20260805103249Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_last_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17930007667830843643)
,p_plug_name=>'Creating ORDS RESTful Services in Oracle APEX'
,p_static_id=>'creating-ords-restful-services-in-oracle-apex'
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'',
'    <p>',
'        To create <strong>ORDS (Oracle REST Data Services)</strong> RESTful services in Oracle APEX,',
unistr('        navigate to <strong>SQL Workshop \2192 RESTful Services</strong> where you can define your'),
'        modules, templates, and handlers.',
'    </p>',
'',
'    <p>',
'        The following steps explain how to build your first ORDS REST API.',
'    </p>',
'',
'    <hr>',
'',
'    <h3>Step 1: Register Your Schema with ORDS</h3>',
'',
'    <p>',
'        Before creating REST endpoints, your database schema must be REST-enabled.',
'    </p>',
'',
'    <ol>',
'        <li>Log in to your <strong>Oracle APEX Workspace</strong>.</li>',
'        <li>Navigate to <strong>SQL Workshop</strong>.</li>',
'        <li>Select <strong>RESTful Services</strong>.</li>',
'        <li>',
'            If your schema is not registered, click',
'            <strong>Register Schema with ORDS</strong>.',
'        </li>',
'        <li>',
'            Set <strong>Select Schema Access</strong> to',
'            <strong>Enabled</strong> and click',
'            <strong>Save/Register</strong>.',
'        </li>',
'    </ol>',
'',
'    <hr>',
'',
'    <h3>Step 2: Create a RESTful Module</h3>',
'',
'    <p>',
'        A module acts as a container that groups multiple related REST endpoints.',
'    </p>',
'',
'    <ol>',
'        <li>Open <strong>Modules</strong> from the RESTful Services page.</li>',
'        <li>Click <strong>Create Module</strong>.</li>',
'        <li>Configure the following settings:',
'            <ul>',
'                <li><strong>Module Name:</strong> A descriptive name (e.g., <code>employees_api</code>).</li>',
'                <li><strong>Base Path:</strong> The URL path (e.g., <code>/hr/</code>).</li>',
'                <li><strong>Is Published:</strong> Set to <strong>On</strong>.</li>',
'            </ul>',
'        </li>',
'        <li>Click <strong>Create Module</strong>.</li>',
'    </ol>',
'',
'    <hr>',
'',
'    <h3>Step 3: Create a Resource Template</h3>',
'',
'    <p>',
'        Templates define the URL path for a specific resource inside the module.',
'    </p>',
'',
'    <ol>',
'        <li>Open your module and select <strong>Resource Templates</strong>.</li>',
'        <li>Click <strong>Create Template</strong>.</li>',
'        <li>',
'            Enter a <strong>URI Template</strong> such as',
'            <code>records/</code> or',
'            <code>records/:id</code>.',
'        </li>',
'        <li>Click <strong>Create Template</strong>.</li>',
'    </ol>',
'',
'    <hr>',
'',
'    <h3>Step 4: Define a HTTP Resource Handler</h3>',
'',
'    <p>',
'        A handler contains the SQL or PL/SQL logic that executes when the REST endpoint is called.',
'    </p>',
'',
'    <ol>',
'        <li>Select the newly created template and click <strong>Create Handler</strong>.</li>',
'        <li>Configure the handler properties:',
'            <ul>',
'                <li>',
'                    <strong>Method:</strong>',
'                    Choose an HTTP method such as',
'                    <code>GET</code>,',
'                    <code>POST</code>,',
'                    <code>PUT</code>, or',
'                    <code>DELETE</code>.',
'                </li>',
'                <li>',
'                    <strong>Source Type:</strong>',
'                    Choose <strong>Query</strong> (returns JSON automatically)',
'                    or <strong>PL/SQL</strong> (for custom business logic).',
'                </li>',
'                <li>',
'                    <strong>Source:</strong>',
'                    Enter the SQL query or PL/SQL block.',
'                    <br>',
'                    Example:',
'                    <pre style="background:#f5f5f5;padding:10px;border-radius:5px;">',
'SELECT *',
'FROM emp;',
'                    </pre>',
'                </li>',
'            </ul>',
'        </li>',
'        <li>Click <strong>Create Handler</strong>.</li>',
'    </ol>',
'',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260805103226Z')
,p_updated_on=>wwv_flow_imp.dz('20260805103226Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(23862454718812722083)
,p_plug_name=>'Oracle APEX RESTful Services (ORDS)'
,p_static_id=>'oracle-apex-restful-services-ords'
,p_region_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'Y'
,p_plug_template=>2675494171183407654
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_plug_item_display_point=>'ABOVE'
,p_plug_query_num_rows=>15
,p_region_image=>'#APP_FILES#icons/app-icon-512.png'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260804085231Z')
,p_updated_on=>wwv_flow_imp.dz('20260804085231Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
