wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17930007928578843646)
,p_plug_name=>'GET All Data'
,p_static_id=>'get-all-data'
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-expanded:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    To create a <strong>GET RESTful service to retrieve all data</strong> from a table in Oracle APEX,',
'    you must configure a <strong>REST Module</strong>, a <strong>Resource Template</strong>, and a',
'    <strong>GET Resource Handler</strong> via ORDS (Oracle REST Data Services).',
'</p>',
'',
'<div style="display:flex; gap:30px; align-items:flex-start; margin-top:20px;">',
'',
'    <!-- Left Side Image -->',
'    <div style="flex:1;">',
'        <img src="#APP_FILES#GET all data.png"',
'             style="width:100%; max-width:900px; border:1px solid #ddd;"',
'             alt="Get All Data">',
'    </div>',
'',
'    <!-- Right Side Steps -->',
'    <div style="flex:1;">',
'        <h4><u>Create an ORDS to fetch All Data</u></h4>',
'',
'        <ol>',
'            <li>Go to Oracle APEX <strong>SQL Workshop</strong>.</li>',
'            <li>Open <strong>RESTful Services</strong>.</li>',
unistr('            <li>Click <strong>Modules</strong> \2192 <strong>Create Module</strong>.</li>'),
'            <li>Enter the <strong>Module Name</strong> and <strong>Base Path</strong>, then click <strong>Create</strong>.</li>',
'            <li>Create a <strong>Template</strong> and enter the <strong>URI Template</strong>.</li>',
'            <li>Create a <strong>Handler</strong>.</li>',
'            <li>Select <strong>Method = GET</strong> and <strong>Source Type = Collection Query</strong>.</li>',
'            <li>Enter the SQL query in the <strong>Source</strong> section.</li>',
'            <li>Click <strong>Create</strong>.</li>',
'            <li><strong>URL to check</strong>: <a href="https://oracleapex.com/ords/archi_04/meetings/data" target="_blank"> https://oracleapex.com/ords/archi_04/meetings/data </a> </li>',
'        </ol>',
'    </div>',
'',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260805125520Z')
,p_updated_on=>wwv_flow_imp.dz('20260812104954Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17930008278784843649)
,p_plug_name=>'GET Image'
,p_static_id=>'get-image'
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>60
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>To retrieve an image from the database via an Oracle APEX RESTful Services(ORDS) using a GET method and a parameter, you must <strong>configure the Source Type as a Media Resource and provide a SQL query where the first column is the MIME type and'
||' the second column is the image BLOB.</strong></p>',
'<div style="display:flex; gap:30px; align-items:flex-start; margin-top:20px;">',
'',
'    <!-- Left Side Image -->',
'    <div style="flex:1;">',
'        <img src="#APP_FILES#GET Media Source.png"',
'             style="width:100%; max-width:900px; border:1px solid #ddd;"',
'             alt="GET image">',
'    </div>',
'',
'    <!-- Right Side Steps -->',
'    <div style="flex:1;">',
'        <h4><u>Create an ORDS to fetch image using parameter</u></h4>',
'',
'        <ol>',
'            <li>Go to Oracle APEX <strong>SQL Workshop</strong>.</li>',
'            <li>Open <strong>RESTful Services</strong>.</li>',
unistr('            <li>Click <strong>Modules</strong> \2192 <strong>Create Module</strong>.</li>'),
'            <li>Enter the <strong>Module Name</strong> and <strong>Base Path</strong>, then click <strong>Create</strong>.</li>',
'            <li>Create a <strong>Template</strong> and enter the <strong>URI Template</strong> and <strong>parameter</strong></li>',
'            <li>Create a <strong>Handler</strong>.</li>',
'            <li>Select <strong>Method = GET</strong> and <strong>Source Type = Media Resource</strong>.</li>',
'            <li>Enter the SQL query in the <strong>Source</strong> section.</li>',
'            <li>Click <strong>Create</strong>.</li>',
'            <li>Create <strong>Parameters</strong></li>',
'            <li><strong>URL to check</strong>: <a href="https://oracleapex.com/ords/archi_04/get/product" target="_blank"> https://oracleapex.com/ords/archi_04/get/product </a> </li>',
'            <li><strong>To pass the value in Parameter</strong>: <a href="https://oracleapex.com/ords/archi_04/get/product?PRODUCT_ID=414141414141" target="_blank"> https://oracleapex.com/ords/archi_04/get/product?PRODUCT_ID=414141414141 </a></li>',
'        </ol>',
'    </div>',
'',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
