wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(25129113520217245510)
,p_event_id=>wwv_flow_imp.id(25129113417080245509)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'var propertyId   = $v("P3_PROPERTY_ID");',
    'var propertyType = $v("P3_PROPERTY_TYPE");',
    'var status       = $v("P3_PROPERTY_AVAILABILITY_STATUS");',
    '',
    '// Show popup only if ALL fields are empty',
    'if (!propertyId && !propertyType && !status) {',
    '    apex.message.alert("Please select at least one filter.");',
    '    return;',
    '}',
    '',
    'var url = "https://oracleapex.com/ords/archi_04/property/get?";',
    '',
    'var params = [];',
    '',
    'if (propertyId) {',
    '    params.push("PROPERTY_ID=" + encodeURIComponent(propertyId));',
    '}',
    '',
    'if (propertyType) {',
    '    params.push("PROPERTY_TYPE=" + encodeURIComponent(propertyType));',
    '}',
    '',
    'if (status) {',
    '    params.push("PROPERTY_AVAILABILITY_STATUS=" + encodeURIComponent(status));',
    '}',
    '',
    'url += params.join("&");',
    '',
    'console.log(url);',
    'window.open(url, "_blank");')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20260806093829Z')
,p_updated_on=>wwv_flow_imp.dz('20260806100449Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
