wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(25129113937505245514)
,p_plug_name=>'POST Method'
,p_static_id=>'postmethod'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>To create a RESTful service using the <strong>POST</strong> methhod in Oracle APEX, you configure a Resource Handler with a <strong>PL/SQL source type</strong> that automatically maps incoming JSON payload fields to PL/SQL bind variables. This all'
||'ows you to safely insert or process incoming data within your Oracle databse.</p>',
'<div style="font-family:Arial,Helvetica,sans-serif;line-height:1.8;color:#333;">',
'',
unistr('    <h3 style="color:#0b4f9c;">\D83D\DEE0\FE0F 1. Register the Schema with ORDS</h3>'),
'',
'    <p>',
'        Before creating web services, your database schema must be enabled for ORDS.',
'    </p>',
'',
'    <ul>',
unistr('        <li>Navigate to <b>SQL Workshop \2192 RESTful Services</b>.</li>'),
'        <li>Click <b>Register Schema with ORDS</b> (if not already registered).</li>',
'        <li>Provide a <b>Schema Alias</b> and click <b>Save</b>.</li>',
'    </ul>',
'',
'    <hr>',
'',
unistr('    <h3 style="color:#0b4f9c;">\D83D\DCE6 2. Create the REST Module and Template</h3>'),
'',
'    <p>',
'        A <b>Module</b> groups your endpoints, while a <b>Template</b> defines the URL path.',
'    </p>',
'',
'    <ol>',
'        <li>Open <b>RESTful Services</b> and click <b>Create Module</b>.</li>',
'        <li>',
'            Set:',
'            <ul>',
'                <li><b>Module Name:</b> <code>v1</code></li>',
'                <li><b>Base Path:</b> <code>/v1/</code></li>',
'            </ul>',
'            Click <b>Create Module</b>.',
'        </li>',
'        <li>Inside the module, click <b>Create Template</b>.</li>',
'        <li>',
'            Set <b>URI Template</b> to',
'            <code>employees/</code>',
'            and click <b>Apply Changes</b>.',
'        </li>',
'    </ol>',
'',
'    <hr>',
'',
unistr('    <h3 style="color:#0b4f9c;">\2699\FE0F 3. Create the POST Resource Handler</h3>'),
'',
'    <p>',
'        The handler contains the PL/SQL code executed when the endpoint is called.',
'    </p>',
'',
'    <ol>',
'        <li>Inside the template, click <b>Create Handler</b>.</li>',
'        <li>Set <b>Method</b> to <b>POST</b>.</li>',
'        <li>Set <b>Source Type</b> to <b>PL/SQL</b>.</li>',
'        <li>Paste the following PL/SQL into the <b>Source</b> section.</li>',
'    </ol>',
'',
'<pre style="background:#f4f4f4;padding:15px;border-radius:6px;overflow:auto;">',
'BEGIN',
'',
'    INSERT INTO emp (',
'        emp_name,',
'        job_title,',
'        department_id',
'    )',
'    VALUES (',
'        :name,',
'        :job,',
'        :dept_id',
'    );',
'',
'    -- Return HTTP Status Code',
'    :status := 201;',
'',
'END;',
'</pre>',
'',
'    <hr>',
'',
unistr('    <h3 style="color:#0b4f9c;">\D83D\DCCB 4. Map the HTTP Parameters</h3>'),
'',
'    <p>',
'        Map the incoming JSON values to PL/SQL bind variables.',
'    </p>',
'',
'    <ol>',
'        <li>Scroll to the <b>Parameters</b> section.</li>',
'        <li>Click <b>Add Row</b>.</li>',
'        <li>Add the following parameters.</li>',
'    </ol>',
'',
'    <table style="border-collapse:collapse;width:100%;text-align:left;">',
'        <thead style="background:#0b4f9c;color:white;">',
'            <tr>',
'                <th style="padding:10px;border:1px solid #ccc;">Name</th>',
'                <th style="padding:10px;border:1px solid #ccc;">Bind Variable</th>',
'                <th style="padding:10px;border:1px solid #ccc;">Access Method</th>',
'                <th style="padding:10px;border:1px solid #ccc;">Source Type</th>',
'                <th style="padding:10px;border:1px solid #ccc;">Data Type</th>',
'            </tr>',
'        </thead>',
'        <tbody>',
'            <tr>',
'                <td style="padding:10px;border:1px solid #ccc;">name</td>',
'                <td style="padding:10px;border:1px solid #ccc;">name</td>',
'                <td style="padding:10px;border:1px solid #ccc;">IN</td>',
'                <td style="padding:10px;border:1px solid #ccc;">HTTP Body</td>',
'                <td style="padding:10px;border:1px solid #ccc;">STRING</td>',
'            </tr>',
'            <tr>',
'                <td style="padding:10px;border:1px solid #ccc;">job</td>',
'                <td style="padding:10px;border:1px solid #ccc;">job</td>',
'                <td style="padding:10px;border:1px solid #ccc;">IN</td>',
'                <td style="padding:10px;border:1px solid #ccc;">HTTP Body</td>',
'                <td style="padding:10px;border:1px solid #ccc;">STRING</td>',
'            </tr>',
'            <tr>',
'                <td style="padding:10px;border:1px solid #ccc;">dept_id</td>',
'                <td style="padding:10px;border:1px solid #ccc;">dept_id</td>',
'                <td style="padding:10px;border:1px solid #ccc;">IN</td>',
'                <td style="padding:10px;border:1px solid #ccc;">HTTP Body</td>',
'                <td style="padding:10px;border:1px solid #ccc;">INT</td>',
'            </tr>',
'            <tr>',
'                <td style="padding:10px;border:1px solid #ccc;">X-APEX-STATUS-CODE</td>',
'                <td style="padding:10px;border:1px solid #ccc;">status</td>',
'                <td style="padding:10px;border:1px solid #ccc;">OUT</td>',
'                <td style="padding:10px;border:1px solid #ccc;">RESPONSE</td>',
'                <td style="padding:10px;border:1px solid #ccc;">INT</td>',
'            </tr>',
'        </tbody>',
'    </table>',
'',
'    <hr>',
'',
unistr('    <h3 style="color:#0b4f9c;">\D83D\DE80 5. Test the Endpoint in Postman</h3>'),
'',
'    <p>Your endpoint URL will look similar to:</p>',
'',
'<pre style="background:#f4f4f4;padding:12px;border-radius:6px;">',
'https://your-server.com/ords/schema_alias/v1/employees/',
'</pre>',
'',
'    <ol>',
'        <li>Open <b>Postman</b>.</li>',
'        <li>Create a new request.</li>',
'        <li>Select the <b>POST</b> method.</li>',
'        <li>Enter the ORDS endpoint URL.</li>',
'        <li>',
unistr('            Go to <b>Body \2192 raw \2192 JSON</b> and paste:'),
'        </li>',
'    </ol>',
'',
'<pre style="background:#f4f4f4;padding:15px;border-radius:6px;overflow:auto;">',
'{',
'    "name": "Jane Doe",',
'    "job": "Software Engineer",',
'    "dept_id": 10',
'}',
'</pre>',
'',
'    <ol start="6">',
'        <li>Click <b>Send</b>.</li>',
'        <li>If everything is configured correctly, the response status should be <b>201 Created</b>.</li>',
'    </ol>',
'',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260807054128Z')
,p_updated_on=>wwv_flow_imp.dz('20260810060201Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
/
